using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed metadata retrieval: JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");
Console.WriteLine($"  Kind: {personInfo.Kind}");
Console.WriteLine($"  Properties: {personInfo.Properties.Count}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"  Serialized: {json}");

// 2) Probe without throwing using TryGetTypeInfo
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? foundInfo))
{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded: {foundInfo!.Type.Name}");
}

// Now probe for a type the resolver *can* resolve (DefaultJsonTypeInfoResolver
// handles any type), so let's demo the "not available" path by using a resolver
// that only handles Person.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new LimitedResolver()
};

if (limitedOptions.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("\nLimited resolver: Person IS available");
else
    Console.WriteLine("\nLimited resolver: Person is NOT available");

if (limitedOptions.TryGetTypeInfo(typeof(Order), out _))
    Console.WriteLine("Limited resolver: Order IS available");
else
    Console.WriteLine("Limited resolver: Order is NOT available");

// --- Types ---
record Person(string Name, int Age);
record Order(int Id, decimal Total);

// --- A resolver that only knows about Person ---
class LimitedResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
    {
        if (type == typeof(Person))
            return _inner.GetTypeInfo(type, options);
        return null; // signals "not available"
    }
}

